/** The most frames per second the surface may attach: the display's rate while it is in front, lower while it is in the background. A surface that paints only on change paints less. A hidden surface paints nothing whatever its pace. */
export interface SurfacePace {
  type: "pace";
  surface: SurfaceId;
  fps: number;
}

/** How often the surface means to paint from now on: 0 when it paints only on change (a document), 60 while it animates. The compositor plans its frames and its live budget by it. */
export interface SurfaceRate {
  type: "rate";
  surface: SurfaceId;
  fps: number;
}
